{% extends "smart_power/templates/print/base_rtl.html" %}
{% block title %}<h2>{{ doc.title }}</h2>{% endblock %}
{% block body %}
{% if doc.home %}<p><b>{{ _("Your Home Page") }}:</b> {{ doc.home }}</p>{% endif %}
{% if doc.menu %}<p><b>{{ _("Your Menu") }}:</b> {{ doc.menu }}</p>{% endif %}
<h4>{{ _("Top Tasks") }}</h4>
{%- for t in doc.tasks if t.is_top %}
<p><b>{{ loop.index }}. {{ t.task }}</b></p>
<ol>{% for s in (t.steps or "").split("\n") if s.strip() %}<li>{{ s }}</li>{% endfor %}</ol>
{%- endfor %}
<table class="sp-table"><thead><tr><th>{{ _("Always") }}</th><th>{{ _("Never") }}</th></tr></thead>
<tbody><tr>
<td><ul>{% for s in (doc.dos or "").split("\n") if s.strip() %}<li>{{ s }}</li>{% endfor %}</ul></td>
<td><ul>{% for s in (doc.donts or "").split("\n") if s.strip() %}<li>{{ s }}</li>{% endfor %}</ul></td>
</tr></tbody></table>
{% endblock %}
